// 사우나우 자체 제작 컬러 일러스트 — sauna-now.dc.html(비교안 B)에서 패스 보존 추출.
// 향후 아이콘팩으로 분리 가능하도록 일관 컴포넌트 API로 래핑.
// 정적 SVG라 원본 마크업을 그대로 렌더(display:contents 래퍼 → 부모 레이아웃에 직접 참여).

function raw(svg: string) {
  function Illustration() {
    return (
      <span
        style={{ display: "contents" }}
        dangerouslySetInnerHTML={{ __html: svg }}
      />
    );
  }
  return Illustration;
}

